 if(bi<25||bi>=C.length)return null;
 const bH=H.slice(bi-20,bi),bL=L.slice(bi-20,bi),bV=V.slice(bi-20,bi);
 const res=Math.max(...bH),sup=Math.min(...bL);
 const range=(res-sup)/C[bi];
 if(!(range>=0.002&&range<=0.030))return {ok:false,why:'نطاق التجميع خارج [0.2% - 3%]: '+(range*100).toFixed(2)+'%'};
 const close=C[bi],open15=(bi>0?C[bi-1]:C[bi]);
 if(!(close>res))return {ok:false,why:'لا إغلاق فوق المقاومة'};
