 const vr=avgV>0?V[bi]/avgV:0;
 if(!(vr>=1.8))return {ok:false,why:'حجم ضعيف ×'+vr.toFixed(2)};
 const a=atr(H.slice(0,bi+1),L.slice(0,bi+1),C.slice(0,bi+1),14);
 if(a==null||a<=0)return {ok:false,why:'ATR غير صالح'};
 const crange=(H[bi]-L[bi])/a;
 if(!(crange<=2.5))return {ok:false,why:'مدى الكسر كبير '+(crange.toFixed(1))+'×ATR'};
 const dist=(close-res)/(res||1e-9);
 if(!(dist>=0&&dist<=0.010))return {ok:false,why:'السعر بعيد عن المقاومة '+(dist*100).toFixed(2)+'%'};
 const rNow=rsi(C.slice(0,bi+1),14),rPrev=rsi(C.slice(0,bi-2),14);
 if(!(rNow>rPrev&&rNow>=40))return {ok:false,why:'لا تحسن RSI ('+Math.round(rPrev)+'→'+Math.round(rNow)+')'};
 const crossUp=rPrev<=50&&rNow>50;
 const sl=Math.min(L[bi]*0.9995,res*0.9985);
 const risk=close-sl;
 if(!(risk>0&&risk/close<=0.025))return {ok:false,why:'وقف غير فني/واسع'};
 return {ok:true,res,vr,crange,dist,rNow,rPrev,crossUp,sl,risk,entry:close,
  t1:close+risk,t2:close+risk*2,t3:close+risk*3,range};
}
