  setStatus('⏳ جلب شموع '+sym+' على '+tfLabel(tf)+'...');
  const eq=clampNum(+$('equity').value,10,1e9,1000);
  const rk=clampNum(+$('risk').value,0.1,5,1.5);
  try{
    const [kl,tick]=await Promise.all([
      fetchJson(`/api/v3/klines?symbol=${sym}&interval=${tf}&limit=400`),
      fetchJson(`/api/v3/ticker/24hr?symbol=${sym}`).catch(()=>null)
    ]);
    if(my!==state.reqId) return;
    if(!Array.isArray(kl)||kl.length<61) throw new Error('لا توجد شموع كافية لهذه العملة/الفريم');
    const closed=kl.slice(0,-1);
    const candles=closed.map(k=>({t:+k[0],o:+k[1],h:+k[2],l:+k[3],c:+k[4],v:+k[5]}));
    const res=SE.analyze(closed,{sym,interval:tf,livePrice:tick?+tick.lastPrice:0,equity:eq,riskPct:rk});
    state.res=res; state.candles=candles; state.tick=tick;
    render(res,candles,tick);
    setStatus('✅ '+sym+' • '+tfLabel(tf)+' — '+res.stateLabel);
    updateUrl(sym,tf);
    loadMtf(sym,tf);
    if(auto.checked) armAuto();
  }catch(e){
    if(my!==state.reqId) return;
    showErr(friendlyErr(e));
    setStatus('❌ تعذر الفحص');
  }finally{
    if(my===state.reqId){setBusy(false);showLoad(false);}
  }
}
```

`friendlyErr`: if message includes 400 or 'HTTP 400' → "الرمز غير موجود أو غير متاح على Binance سبوت".

fetchJson uses host fallback. Note when the symbol is invalid, each host returns 400; we should not fall back on 400 (definitive) — break early. Implement: if status 400 → throw new Error('HTTP 400') immediately (no host fallback). Retry only on network/5xx/451.

```js
async function fetchJson(path){
 let lastErr;
 for(const host of HOSTS){
   const ctl=new AbortController();
   const to=setTimeout(()=>ctl.abort(), 12000);
   try{
     const r=await fetch(host+path,{signal:ctl.signal,cache:'no-store'});
     clearTimeout(to);
     if(r.ok) return await r.json();
     if(r.status===400||r.status===404){throw new Error('HTTP '+r.status);}
     lastErr=new Error('HTTP '+r.status);
   }catch(e){
     clearTimeout(to);
     if(String(e.message).indexOf('HTTP 4')===0) throw e;
     lastErr=e;
   }
 }
 throw lastErr||new Error('network');
}
```
Careful `throw` inside try is caught by catch — but then rethrown by the check `if HTTP 4` → fine, break loop. Actually it throws from catch, exiting.

