Now code for batch:
```js
async function startBatch(){
  if(state.batchRunning){state.batchToken++; state.batchRunning=false; $('batchGo').textContent='🚀 امسح أعلى 60 عملة'; return;}
  const tf=state.tf;
  const token=++state.batchToken;
  state.batchRunning=true;
  $('batchGo').textContent='⏹ إيقاف المسح';
  setProg(1,'جلب قائمة العملات...');
  try{
    const all=await loadSymbols();
    const list=all.slice(0,60); // already filtered/sorted
    if(token!==state.batchToken) return;
    setProg(4,'فحص '+list.length+' عملة على '+tfLabel(tf)+'...');
    const found=[]; const CONC=6;
    for(let i=0;i<list.length;i+=CONC){
      if(token!==state.batchToken) return;
      const batch=list.slice(i,i+CONC);
      const rs=await Promise.allSettled(batch.map(async s=>{
        const kl=await fetchJson(`/api/v3/klines?symbol=${s}&interval=${tf}&limit=400`);
        if(!Array.isArray(kl)||kl.length<61) return null;
        const r=SE.analyze(kl.slice(0,-1),{sym:s,interval:tf,equity:...,riskPct:...});
        return (r.state==='active'||r.state==='pending'||r.state==='weak')?r:null;
      }));
      rs.forEach(x=>{if(x.status==='fulfilled'&&x.value)found.push(x.value);});
      const done=Math.min(list.length,i+CONC);
      setProg(4+done/list.length*94, 'فحص '+done+'/'+list.length+' — فرص: '+found.length);
      await sleep(60);
    }
    if(token!==state.batchToken) return;
    renderBatch(found,tf);
    setProg(100,'تم — '+found.length+' فرصة');
  }catch(e){
    if(token===state.batchToken){ setProg(0,'فشل المسح'); $('scanOut').innerHTML='<div class="empty">❌ '+esc(friendlyErr(e))+'</div>'; }
  }finally{
    if(token===state.batchToken){state.batchRunning=false;$('batchGo').textContent='🚀 امسح أعلى 60 عملة';}
  }
}
```

