from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errs=[]
        self.void={'meta','link','br','img','input','hr','source','area','base','col','embed','param','track','wbr'}
    def handle_starttag(self,tag,attrs):
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self,tag):
        if tag in self.void: return
        if not self.stack: self.errs.append('extra </%s>'%tag); return
        if self.stack[-1]==tag: self.stack.pop()
        else: self.errs.append('mismatch </%s> expected </%s>'%(tag,self.stack[-1]))
p=P(); p.feed(s)
print('unclosed:',p.stack)
print('errors:',p.errs[:5])
